# Surah Al-An'am (chapter 6) — part 6: ayat 54-63 (IDs 843-852)
SURAH = 6

ENTRIES = {
843: (
"اور جب آپ کے پاس — وہ لوگ آئیں جو ہماری آیات پر ایمان رکھتے ہیں — تو کہہ دیں: تم پر سلام ہو — تمہارے رب نے — اپنے اوپر — رحمت — لکھ — دی ہے — یہ کہ — جو کوئی تم میں سے — برائی — جہالت میں کرے — پھر اس کے بعد توبہ کرے اور اصلاح کرے — تو — بے شک — وہ — بخشش والا — مہربان ہے",
"""۱۔ ایمان والوں کا استقبال — سلامتی۔
۲۔ ’’وَإِذَا جَاءَكَ الَّذِينَ يُؤْمِنُونَ بِآيَاتِنَا فَقُلْ سَلَامٌ عَلَيْكُمْ‘‘ — اور جب آپ کے پاس — وہ لوگ آئیں جو ہماری آیات پر ایمان رکھتے ہیں — تو کہہ دیں: تم پر سلام ہو — یعنی ایمان والوں کا استقبال — سلامتی اور دعا کے ساتھ۔
۳۔ ’’كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ الرَّحْمَۃَ‘‘ — تمہارے رب نے — اپنے اوپر — رحمت — لکھ — دی ہے — یعنی اللہ کی رحمت — اللہ کا خود اپنے اوپر حق مقرر ہے۔
۴۔ ’’أَنَّهُ مَنْ عَمِلَ مِنكُمْ سُوءًا بِجَهَالَۃٍ ثُمَّ تَابَ مِن بَعْدِهِ وَأَصْلَحَ فَأَنَّهُ غَفُورٌ رَّحِيمٌ‘‘ — یہ کہ — جو کوئی تم میں سے — برائی — جہالت میں کرے — پھر اس کے بعد توبہ کرے اور اصلاح کرے — تو — بے شک — وہ — بخشش والا — مہربان ہے — یعنی توبہ اور اصلاح — مغفرت کی شرط ہے۔
۵۔ عملی سبق: ایمان والوں کو عزت سے دیکھو؛ توبہ اور اصلاح کرو؛ اللہ کی رحمت پر بھروسہ کرو۔"""
),
844: (
"اور اسی طرح ہم — آیات — کو تفصیل سے بیان کرتے ہیں — اور اسی لیے کہ — مجرموں کا راستہ — واضح ہو جائے",
"""۱۔ آیات کی تفصیل — گمراہوں کی راہ کو واضح کرتی ہے۔
۲۔ ’’وَكَذَٰلِكَ نُفَصِّلُ الْآيَاتِ وَلِتَسْتَبِينَ سَبِيلُ الْمُجْرِمِينَ‘‘ — اور اسی طرح ہم — آیات — کو تفصیل سے بیان کرتے ہیں — اور اسی لیے کہ — مجرموں کا راستہ — واضح ہو جائے — یعنی اللہ آیات کافروں کو بھی کھول کھول کر بیان کرتا ہے — تاکہ مجرموں کی راہ نمایاں ہو۔
۳۔ عملی سبق: آیات پر غور کرو؛ برے راستوں سے دور رہو۔"""
),
845: (
"کہہ دیں: مجھے منع کیا گیا ہے کہ — جنہیں تم — اللہ کے سوا — پکارتے ہو — ان — کی — عبادت کروں — کہہ دیں: میں تمہاری خواہشات کی پیروی نہیں کرتا — میں — پھر — گمراہ ہو جاؤں — اور ہدایت پانے والوں میں سے نہ رہوں",
"""۱۔ نبی ﷺ کی — اللہ کے سوا — عبادت سے برات۔
۲۔ ’’قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِنْ دُونِ اللّٰہِ‘‘ — کہہ دیں: مجھے منع کیا گیا ہے کہ — جنہیں تم — اللہ کے سوا — پکارتے ہو — ان — کی — عبادت کروں — یعنی صرف اللہ کی عبادت۔
۳۔ ’’قُلْ لَا أَتَّبِعُ أَهْوَاءَكُمْ قَدْ ضَلَلْتُ إِذًا وَمَا أَنَا مِنَ الْمُهْتَدِينَ‘‘ — کہہ دیں: میں تمہاری خواہشات کی پیروی نہیں کرتا — میں — پھر — گمراہ ہو جاؤں — اور ہدایت پانے والوں میں سے نہ رہوں — یعنی خواہشات کی پیروی — گمراہی ہے۔
۴۔ عملی سبق: خواہشات کے بجائے — وحی کی پیروی کرو۔"""
),
846: (
"کہہ دیں: میں — اپنے رب کی طرف سے — واضح دلیل — پر ہوں — اور تم — اس — کو جھٹلا چکے ہو — میرے — پاس — وہ نہیں جو تم جلدی مانگتے ہو — حکم — صرف اللہ کا ہے — وہ حق بیان کرتا ہے — اور وہ — سب سے بہتر — فیصلہ کرنے والا ہے",
"""۱۔ نبی ﷺ — اپنے رب کی طرف سے — واضح دلیل پر — ہیں۔
۲۔ ’’قُلْ إِنِّي عَلَىٰ بَيِّنَۃٍ مِّن رَّبِّي وَكَذَّبْتُم بِهِ‘‘ — کہہ دیں: میں — اپنے رب کی طرف سے — واضح دلیل — پر ہوں — اور تم — اس — کو جھٹلا چکے ہو — یعنی نبی ﷺ دعویٰ کے بغیر — دلیل پر ہیں۔
۳۔ ’’مَا عِندِي مَا تَسْتَعْجِلُونَ بِهِ‘‘ — میرے — پاس — وہ نہیں جو تم جلدی مانگتے ہو — یعنی نبی ﷺ — خود — سزا کے اوقات — نہیں جانتے۔
۴۔ ’’إِنِ الْحُكْمُ إِلَّا لِلّٰہِ يَقُصُّ الْحَقَّ وَهُوَ خَيْرُ الْفَاصِلِينَ‘‘ — حکم — صرف اللہ کا ہے — وہ حق بیان کرتا ہے — اور وہ — سب سے بہتر — فیصلہ کرنے والا ہے — یعنی حتمی فیصلہ — اللہ کا ہے۔
۵۔ عملی سبق: اللہ کے فیصلے کا انتظار کرو؛ جلد بازی مت کرو۔"""
),
847: (
"کہہ دیں: اگر — میرے — پاس — ہوتا جو تم جلدی مانگتے ہو — تو — میرے اور تمہارے درمیان — کا معاملہ — فیصلہ ہو جاتا — اور اللہ — ظالموں — کو — سب سے بہتر جانتا ہے",
"""۱۔ نبی ﷺ کے پاس — سزا کا وقت — نہیں۔
۲۔ ’’قُل لَّوْ أَنَّ عِندِي مَا تَسْتَعْجِلُونَ بِهِ لَقُضِيَ الْأَمْرُ بَيْنِي وَبَيْنَكُمْ وَاللّٰہُ أَعْلَمُ بِالظَّالِمِينَ‘‘ — کہہ دیں: اگر — میرے — پاس — ہوتا جو تم جلدی مانگتے ہو — تو — میرے اور تمہارے درمیان — کا معاملہ — فیصلہ ہو جاتا — اور اللہ — ظالموں — کو — سب سے بہتر جانتا ہے — یعنی اللہ — ظالموں کو — ان کے اعمال کے مطابق بدلہ دے گا۔
۳۔ عملی سبق: عذاب میں جلد بازی مت کرو؛ اللہ کے فیصلے پر بھروسہ کرو۔"""
),
848: (
"اور — اس — کے — پاس — غیب کی چابیوں (خزانے) ہیں — انہیں اللہ کے سوا کوئی نہیں جانتا — اور وہ — جانتا ہے جو زمین اور سمندر میں ہے — اور — نہیں گرتا کوئی پتہ — مگر وہ اسے جانتا ہے — اور — نہیں — دانہ — زمین کی اندھیریوں میں — اور نہ کوئی تر اور نہ کوئی خشک — مگر — ایک واضح کتاب میں ہے",
"""۱۔ غیب — صرف اللہ جانتا ہے۔
۲۔ ’’وَعِندَهُ مَفَاتِحُ الْغَيْبِ لَا يَعْلَمُهَا إِلَّا هُوَ‘‘ — اور — اس — کے — پاس — غیب کی چابیوں (خزانے) ہیں — انہیں اللہ کے سوا کوئی نہیں جانتا — یعنی غیب کی چابیاں — صرف اللہ کے پاس ہیں۔
۳۔ ’’وَيَعْلَمُ مَا فِي الْبَرِّ وَالْبَحْرِ‘‘ — اور وہ — جانتا ہے جو زمین اور سمندر میں ہے۔
۴۔ ’’وَمَا تَسْقُطُ مِن وَرَقَۃٍ إِلَّا يَعْلَمُهَا وَلَا حَبَّۃٍ فِي ظُلُمَاتِ الْأَرْضِ وَلَا رَطْبٍ وَلَا يَابِسٍ إِلَّا فِي كِتَابٍ مُّبِينٍ‘‘ — اور — نہیں گرتا کوئی پتہ — مگر وہ اسے جانتا ہے — اور — نہیں — دانہ — زمین کی اندھیریوں میں — اور نہ کوئی تر اور نہ کوئی خشک — مگر — ایک واضح کتاب میں ہے — یعنی کوئی ذرہ — اللہ کے بغیر نہیں گرتا۔
۵۔ عملی سبق: غیب کا دعویٰ کرنے والوں سے بچو؛ اللہ کے علم پر ایمان رکھو۔"""
),
849: (
"اور وہی — ہے جو — تمہیں — رات کو وفات (نیند) دیتا ہے اور — جو تم نے دن میں کمایا — اسے جانتا ہے — پھر — اس — میں — تمہیں دوبارہ اٹھاتا ہے تاکہ ایک مقررہ مدت پوری ہو — پھر — اسی — کی طرف تمہاری واپسی ہوگی — پھر وہ تمہیں — جو تم کرتے تھے — بتائے گا",
"""۱۔ رات کی نیند — اللہ کی طرف سے — وفات کی ایک صورت۔
۲۔ ’’وَهُوَ الَّذِي يَتَوَفَّاكُم بِاللَّيْلِ وَيَعْلَمُ مَا جَرَحْتُم بِالنَّهَارِ‘‘ — اور وہی — ہے جو — تمہیں — رات کو وفات (نیند) دیتا ہے اور — جو تم نے دن میں کمایا — اسے جانتا ہے — یعنی نیند — موت کی ایک جھلک ہے۔
۳۔ ’’ثُمَّ يَبْعَثُكُمْ فِيهِ لِيُقْضَىٰ أَجَلٌ مُّسَمًّى‘‘ — پھر — اس — میں — تمہیں دوبارہ اٹھاتا ہے تاکہ ایک مقررہ مدت پوری ہو — یعنی ہر انسان کی — مقررہ — مدت — پوری ہونی ہے۔
۴۔ ’’ثُمَّ إِلَيْهِ مَرْجِعُكُمْ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ‘‘ — پھر — اسی — کی طرف تمہاری واپسی ہوگی — پھر وہ تمہیں — جو تم کرتے تھے — بتائے گا — یعنی قیامت میں — ہر — ایک کو بتایا جائے گا۔
۵۔ عملی سبق: نیند سے — موت کی یاد آتی ہے؛ بروقت عمل کرو۔"""
),
850: (
"اور وہی — بندوں پر — غالب — ہے — اور وہ — تم پر — حفاظت کرنے والے — بھیجتا ہے یہاں تک کہ تم میں سے کسی کو موت آجاتی ہے — ہمارے بھیجے ہوئے (فرشتے) — اس — کی — وفات کرتے ہیں — اور وہ کوتاہی نہیں کرتے",
"""۱۔ اللہ — انسان پر غلبہ رکھنے والا ہے۔
۲۔ ’’وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ وَيُرْسِلُ عَلَيْكُمْ حَفَظَۃً‘‘ — اور وہی — بندوں پر — غالب — ہے — اور وہ — تم پر — حفاظت کرنے والے — بھیجتا ہے — یعنی اللہ تم پر — نگہبان — فرشتے — بھیجتا ہے۔
۳۔ ’’حَتَّىٰ إِذَا جَاءَ أَحَدَكُمُ الْمَوْتُ تَوَفَّتْهُ رُسُلُنَا وَهُمْ لَا يُفَرِّطُونَ‘‘ — یہاں تک کہ تم میں سے کسی کو موت آجاتی ہے — ہمارے بھیجے ہوئے (فرشتے) — اس — کی — وفات کرتے ہیں — اور وہ کوتاہی نہیں کرتے — یعنی موت کا فرشتہ — اللہ کا حکم پورا کرتا ہے۔
۴۔ عملی سبق: ہر وقت — اللہ کے فرشتوں کی حفاظت میں ہو؛ بروقت توبہ کرو۔"""
),
851: (
"پھر — ان — کو — اعزاز کے ساتھ — لوٹایا جائے گا — اس اللہ — کی — طرف جو ان کا حقیقی مولا ہے — دیکھو! فیصلہ — اس — کا ہے — اور وہ — سب سے تیز — حساب لینے والا ہے",
"""۱۔ مرنے کے بعد — حساب۔
۲۔ ’’ثُمَّ رُدُّوا إِلَى اللّٰہِ مَوْلَاهُمُ الْحَقِّ أَلَا لَهُ الْحُكْمُ وَهُوَ أَسْرَعُ الْحَاسِبِينَ‘‘ — پھر — ان — کو — اعزاز کے ساتھ — لوٹایا جائے گا — اس اللہ — کی — طرف جو ان کا حقیقی مولا ہے — دیکھو! فیصلہ — اس — کا ہے — اور وہ — سب سے تیز — حساب لینے والا ہے — یعنی قیامت میں — اللہ کا حساب — تیز — فوری ہوگا۔
۳۔ عملی سبق: حساب کے دن کی تیاری کرو؛ اللہ کو حقیقی مولا سمجھو۔"""
),
852: (
"کہہ دیں: کون ہے — جو تمہیں — سمندر اور صحرا کی اندھیریوں — سے — نجات دلاتا ہے — تم اسے — پکارتے ہو — بآواز آہستہ — اور — چپکے — چپکے — اگر — وہ — ہمیں — اس — سے — نجات دے گا — تو ہم — شکر گزاروں میں سے ہو جائیں گے",
"""۱۔ مشکل میں — سب اللہ کو پکارتے ہیں۔
۲۔ ’’قُلْ مَن يُنَجِّيكُم مِّن ظُلُمَاتِ الْبَرِّ وَالْبَحْرِ تَدْعُونَهُ تَضَرُّعًا وَخُفْيَۃً‘‘ — کہہ دیں: کون ہے — جو تمہیں — سمندر اور صحرا کی اندھیریوں — سے — نجات دلاتا ہے — تم اسے — پکارتے ہو — بآواز آہستہ — اور — چپکے — چپکے — یعنی تکلیف میں — صرف اللہ پکارا جاتا ہے۔
۳۔ ’’لَّئِنْ أَنجَانَا مِنْ هَٰذِهِ لَنَكُونَنَّ مِنَ الشَّاكِرِينَ‘‘ — اگر — وہ — ہمیں — اس — سے — نجات دے گا — تو ہم — شکر گزاروں میں سے ہو جائیں گے — یعنی نجات کے بعد — شکر ادا کرنے کا وعدہ۔
۴۔ عملی سبق: تکلیف میں — اللہ کو پکارو؛ نجات کے بعد شکر ادا کرو۔"""
),
}
